    (lo P E bs fb : Z) (c : pcore) (pad7 pad2 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' (j8 : list byte) (t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 : word),
       ms' = sro_call_ms sp P E bs fb gp tp t0 t1 t2 a4 a5 a6 a7 (wz 0) t3 t4 t5 t6 F fc m'
    /\ munch [(lo, bv_unsigned sp); (E, E + 24)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp + -128)
