Lemma sro_tail : forall (sp : word) (lo P E bs fb : Z) (gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s5x t3 t4 t5 t6 : word)
    (rae s0e s1e s2e s3e s4e s5e s6e s7e s8e s9e s10e s11e : word) (F : bvmap 5 word) fc (m : mem) (E' : ecv) (c : pcore) (pad7 pad2 j8 : list byte) (tot : Z),
  rw_cells asegs m E (ErrCodeCells E') -> ec_ok E' -> (E' = EC_clear \/ http_fail E') -> aapp E 24 -> accessible m E 24 -> E mod 8 = 0 ->
  rw_cells asegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c -> aapp P PARSER_SIZE -> accessible m P PARSER_SIZE -> P mod 8 = 0 ->
  rw_cells asegs m (bv_unsigned sp + -128) ([CB 8 j8; C8 (wz 3); C8 (wz 3)] ++ sro_sv s11e s10e s9e s8e s7e s6e s5e s4e s3e s2e s1e s0e rae) ->
  stk asegs m lo (bv_unsigned sp + -128) -> lo + 128 <= bv_unsigned sp -> aceil <= lo -> 0 <= tot < 2^64 ->
  bv_unsigned rae mod 2 = 0 -> mem_inv asegs m -> ACONST m ->
  evt asegs (fun ms' =>
         ((http_fail E' \/ (E' = EC_clear /\ pc_state c = 11)) /\
            exists a0' a1' a2', ms' = MS (mkR rae sp gp tp t0 t1 t2 s0e s1e a0' a1' a2' a3 a4 a5 a6 a7 s2e s3e s4e s5e s6e s7e s8e s9e s10e s11e t3 t4 t5 t6)
                                          F (ret_pc rae) fc None m (seg_rom asegs)
            /\ stk asegs m lo (bv_unsigned sp))
      \/ ((E' = EC_clear /\ pc_state c <> 11) /\
            exists s5x', ms' = sro_call_ms sp P E bs fb gp tp t0 t1 t2 a4 a5 a6 a7 s5x' t3 t4 t5 t6 F fc m))
    (MS (mkR (wz SRO_RSRET) (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0 t1 t2 (wz E) (wz P) (wz tot) a1 a2 a3 a4 a5 a6 a7
             (wz fb) (wz bs) (wz (P + 72)) s5x (wz (E + 16)) (wz (Z.shiftr (P + 72) 3 + 2147450880)) (wz 11) (wz 1)
             (wz (Z.shiftr E 3 + 2147450880)) (wz (Z.shiftr (E + 16) 3 + 2147450880)) t3 t4 t5 t6)
        F (Z_to_bv 64 SRO_RSRET) fc None m (seg_rom asegs)).
